import java.util.Scanner;

public class Main {
    private static final long MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int len = String.valueOf(n).length();
        long req = mexp(10, len, MOD);
        long num = (mexp(req, n, MOD) - 1 + MOD) % MOD;
        long den = (req - 1 + MOD) % MOD;
        long denInverse = mexp(den, MOD - 2, MOD);
        long result = (num * denInverse % MOD) * n % MOD;
        System.out.println(result);
    }

    private static long mexp(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % mod;
            }
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
}
